  `submissions` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`form_id`,`period_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;


DROP TABLE IF EXISTS `wp_wpforms_analytics_snapshots`;
